WITH valid AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, CONCAT_WS(',', email, job_title) AS email_job_title_key, COALESCE(level, 'UNKNOWN') AS level_clean FROM employees WHERE hire_date > DATE '2023-05-28' AND manager_id IS NOT NULL) SELECT id, full_name, manager_id, hire_date, email_job_title_key, level_clean FROM (SELECT *, RANK() OVER (PARTITION BY job_title ORDER BY salary) AS latest_rank FROM valid) ranked WHERE latest_rank = 1;
